package mx.com.mesaregia.cotizaciones.domain.entity; import jakarta.persistence.*; import lombok.*; import mx.com.mesaregia.cotizaciones.domain.enums.EstadoOutbox; import java.time.LocalDateTime;
@Entity @Table(name="integration_outbox") @Getter @Setter @NoArgsConstructor public class IntegrationOutbox {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_outbox")private Long id;@Column(name="event_id",nullable=false,unique=true,length=80)private String eventId;@Column(nullable=false,length=100)private String tipo;@Column(name="agregado_tipo",nullable=false,length=80)private String agregadoTipo;@Column(name="agregado_id",nullable=false,length=100)private String agregadoId;@Lob @Column(columnDefinition="LONGTEXT")private String payload;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private EstadoOutbox estado=EstadoOutbox.PENDIENTE;@Column(nullable=false)private Integer intentos=0;@Column(name="proximo_intento",nullable=false)private LocalDateTime proximoIntento=LocalDateTime.now();@Column(name="ultimo_error",length=1000)private String ultimoError;@Column(name="creado_en",insertable=false,updatable=false)private LocalDateTime creadoEn;@Column(name="enviado_en")private LocalDateTime enviadoEn;}
